    10→)
    11→
    12→func bytesToBlob(blob []byte) *GoKZG.Blob {
    13→	var ret GoKZG.Blob
    14→	copy(ret[:], blob)
    15→	return &ret
    16→}
    17→
    18→func bytesToCommitment(commitment []byte) (ret GoKZG.KZGCommitment) {
    19→	copy(ret[:], commitment)
    20→	return
    21→}
    22→
    23→func bytesToKZGProof(proof []byte) (ret GoKZG.KZGProof) {
    24→	copy(ret[:], proof)
    25→	return
    26→}
    27→
    28→// Verify performs single or batch verification of commitments depending on the number of given BlobSidecars.
    29→func Verify(blobSidecars ...blocks.ROBlob) error {
    30→	if len(blobSidecars) == 0 {
    31→		return nil
    32→	}
    33→	if len(blobSidecars) == 1 {
    34→		return kzgContext.VerifyBlobKZGProof(
    35→			bytesToBlob(blobSidecars[0].Blob),
    36→			bytesToCommitment(blobSidecars[0].KzgCommitment),
    37→			bytesToKZGProof(blobSidecars[0].KzgProof))
    38→	}
    39→	blobs := make([]GoKZG.Blob, len(blobSidecars))
    40→	cmts := make([]GoKZG.KZGCommitment, len(blobSidecars))
    41→	proofs := make([]GoKZG.KZGProof, len(blobSidecars))
    42→	for i, sidecar := range blobSidecars {
    43→		blobs[i] = *bytesToBlob(sidecar.Blob)
    44→		cmts[i] = bytesToCommitment(sidecar.KzgCommitment)
    45→		proofs[i] = bytesToKZGProof(sidecar.KzgProof)
    46→	}
    47→	return kzgContext.VerifyBlobKZGProofBatch(blobs, cmts, proofs)
    48→}
    49→
    50→// VerifyBlobKZGProofBatch verifies KZG proofs for multiple blobs using batch verification.
    51→// This is more efficient than verifying each blob individually when len(blobs) > 1.
    52→// For single blob verification, it uses the optimized single verification path.
    53→func VerifyBlobKZGProofBatch(blobs [][]byte, commitments [][]byte, proofs [][]byte) error {
    54→	if len(blobs) != len(commitments) || len(blobs) != len(proofs) {
    55→		return errors.Errorf("number of blobs (%d), commitments (%d), and proofs (%d) must match", len(blobs), len(commitments), len(proofs))
    56→	}
    57→
    58→	if len(blobs) == 0 {
    59→		return nil
    60→	}
    61→
    62→	// Optimize for single blob case - use single verification to avoid batch overhead
    63→	if len(blobs) == 1 {
    64→		return kzgContext.VerifyBlobKZGProof(
    65→			bytesToBlob(blobs[0]),
    66→			bytesToCommitment(commitments[0]),
    67→			bytesToKZGProof(proofs[0]))
    68→	}
    69→
    70→	// Use batch verification for multiple blobs
    71→	ckzgBlobs := make([]ckzg4844.Blob, len(blobs))
    72→	ckzgCommitments := make([]ckzg4844.Bytes48, len(commitments))
    73→	ckzgProofs := make([]ckzg4844.Bytes48, len(proofs))
    74→
    75→	for i := range blobs {
    76→		if len(blobs[i]) != len(ckzg4844.Blob{}) {
    77→			return fmt.Errorf("blobs len (%d) differs from expected (%d)", len(blobs[i]), len(ckzg4844.Blob{}))
    78→		}
    79→		if len(commitments[i]) != len(ckzg4844.Bytes48{}) {
    80→			return fmt.Errorf("commitments len (%d) differs from expected (%d)", len(commitments[i]), len(ckzg4844.Blob{}))
    81→		}
    82→		if len(proofs[i]) != len(ckzg4844.Bytes48{}) {
    83→			return fmt.Errorf("proofs len (%d) differs from expected (%d)", len(proofs[i]), len(ckzg4844.Blob{}))
    84→		}
    85→		ckzgBlobs[i] = ckzg4844.Blob(blobs[i])
    86→		ckzgCommitments[i] = ckzg4844.Bytes48(commitments[i])
    87→		ckzgProofs[i] = ckzg4844.Bytes48(proofs[i])
    88→	}
    89→
    90→	valid, err := ckzg4844.VerifyBlobKZGProofBatch(ckzgBlobs, ckzgCommitments, ckzgProofs)
    91→	if err != nil {
    92→		return errors.Wrap(err, "batch verification")
    93→	}
    94→	if !valid {
    95→		return errors.New("batch KZG proof verification failed")
    96→	}
    97→
    98→	return nil
    99→}
   100→
   101→// VerifyCellKZGProofBatchFromBlobData verifies cell KZG proofs in batch format directly from blob data.
   102→// This is more efficient than reconstructing data column sidecars when you have the raw blob data and cell proofs.
   103→// For PeerDAS/Fulu, the execution client provides cell proofs in flattened format via BlobsBundleV2.
   104→// For single blob verification, it optimizes by computing cells once and verifying efficiently.
   105→func VerifyCellKZGProofBatchFromBlobData(blobs [][]byte, commitments [][]byte, cellProofs [][]byte, numberOfColumns uint64) error {
   106→	blobCount := uint64(len(blobs))
   107→	expectedCellProofs := blobCount * numberOfColumns
   108→
   109→	if uint64(len(cellProofs)) != expectedCellProofs {
   110→		return errors.Errorf("expected %d cell proofs, got %d", expectedCellProofs, len(cellProofs))
   111→	}
   112→
   113→	if len(commitments) != len(blobs) {
   114→		return errors.Errorf("number of commitments (%d) must match number of blobs (%d)", len(commitments), len(blobs))
   115→	}
   116→
   117→	if blobCount == 0 {
   118→		return nil
   119→	}
   120→
   121→	// Handle multiple blobs - compute cells for all blobs
   122→	allCells := make([]Cell, 0, expectedCellProofs)
   123→	allCommitments := make([]Bytes48, 0, expectedCellProofs)
   124→	allIndices := make([]uint64, 0, expectedCellProofs)
   125→	allProofs := make([]Bytes48, 0, expectedCellProofs)
   126→
   127→	for blobIndex := range blobs {
   128→		if len(blobs[blobIndex]) != len(Blob{}) {
   129→			return fmt.Errorf("blobs len (%d) differs from expected (%d)", len(blobs[blobIndex]), len(Blob{}))
   130→		}
   131→		// Convert blob to kzg.Blob type
   132→		blob := Blob(blobs[blobIndex])
   133→
   134→		// Compute cells for this blob
   135→		cells, err := ComputeCells(&blob)
   136→		if err != nil {
   137→			return errors.Wrapf(err, "failed to compute cells for blob %d", blobIndex)
   138→		}
   139→
   140→		// Add cells and corresponding data for each column
   141→		for columnIndex := range numberOfColumns {
   142→			cellProofIndex := uint64(blobIndex)*numberOfColumns + columnIndex
   143→			if len(commitments[blobIndex]) != len(Bytes48{}) {
   144→				return fmt.Errorf("commitments len (%d) differs from expected (%d)", len(commitments[blobIndex]), len(Bytes48{}))
   145→			}
   146→			if len(cellProofs[cellProofIndex]) != len(Bytes48{}) {
   147→				return fmt.Errorf("proofs len (%d) differs from expected (%d)", len(cellProofs[cellProofIndex]), len(Bytes48{}))
   148→			}
   149→			allCells = append(allCells, cells[columnIndex])
   150→			allCommitments = append(allCommitments, Bytes48(commitments[blobIndex]))
   151→			allIndices = append(allIndices, columnIndex)
   152→
   153→			allProofs = append(allProofs, Bytes48(cellProofs[cellProofIndex]))
   154→		}
   155→	}
   156→
   157→	// Batch verify all cells
   158→	valid, err := VerifyCellKZGProofBatch(allCommitments, allIndices, allCells, allProofs)
   159→	if err != nil {
   160→		return errors.Wrap(err, "cell batch verification")
   161→	}
   162→	if !valid {
   163→		return errors.New("cell KZG proof batch verification failed")
   164→	}
   165→
   166→	return nil
   167→}
   168→

