     1→package sync
     2→
     3→import (
     4→	"context"
     5→	"time"
     6→
     7→	"github.com/OffchainLabs/prysm/v6/beacon-chain/core/peerdas"
     8→	"github.com/OffchainLabs/prysm/v6/config/params"
     9→	"github.com/OffchainLabs/prysm/v6/consensus-types/blocks"
    10→	"github.com/OffchainLabs/prysm/v6/crypto/bls"
    11→	"github.com/OffchainLabs/prysm/v6/monitoring/tracing"
    12→	"github.com/OffchainLabs/prysm/v6/monitoring/tracing/trace"
    13→	pubsub "github.com/libp2p/go-libp2p-pubsub"
    14→	"github.com/pkg/errors"
    15→)
    16→
    17→const signatureVerificationInterval = 50 * time.Millisecond
    18→
    19→type signatureVerifier struct {
    20→	set     *bls.SignatureBatch
    21→	resChan chan error
    22→}
    23→
    24→type kzgVerifier struct {
    25→	dataColumns []blocks.RODataColumn
    26→	resChan     chan error
    27→}
    28→
    29→// A routine that runs in the background to perform batch
    30→// verifications of incoming messages from gossip.
    31→func (s *Service) verifierRoutine() {
    32→	verifierBatch := make([]*signatureVerifier, 0)
    33→	ticker := time.NewTicker(signatureVerificationInterval)
    34→	for {
    35→		select {
    36→		case <-s.ctx.Done():
    37→			// Clean up currently utilised resources.
    38→			ticker.Stop()
    39→			for i := 0; i < len(verifierBatch); i++ {
    40→				verifierBatch[i].resChan <- s.ctx.Err()
    41→			}
    42→			return
    43→		case sig := <-s.signatureChan:
    44→			verifierBatch = append(verifierBatch, sig)
    45→			if len(verifierBatch) >= s.cfg.batchVerifierLimit {
    46→				verifyBatch(verifierBatch)
    47→				verifierBatch = []*signatureVerifier{}
    48→			}
    49→		case <-ticker.C:
    50→			if len(verifierBatch) > 0 {
    51→				verifyBatch(verifierBatch)
    52→				verifierBatch = []*signatureVerifier{}
    53→			}
    54→		}
    55→	}
    56→}
    57→
    58→// A routine that runs in the background to perform batch
    59→// KZG verifications by draining the channel and processing all pending requests.
    60→func (s *Service) kzgVerifierRoutine() {
    61→	for {
    62→		kzgBatch := make([]*kzgVerifier, 0, 1)
    63→		select {
    64→		case <-s.ctx.Done():
    65→			return
    66→		case kzg := <-s.kzgChan:
    67→			kzgBatch = append(kzgBatch, kzg)
    68→		}
    69→		for {
    70→			select {
    71→			case <-s.ctx.Done():
    72→				return
    73→			case kzg := <-s.kzgChan:
    74→				kzgBatch = append(kzgBatch, kzg)
    75→				continue
    76→			default:
    77→				verifyKzgBatch(kzgBatch)
    78→			}
    79→			break
    80→		}
    81→	}
    82→}
    83→
    84→func (s *Service) validateWithBatchVerifier(ctx context.Context, message string, set *bls.SignatureBatch) (pubsub.ValidationResult, error) {
    85→	_, span := trace.StartSpan(ctx, "sync.validateWithBatchVerifier")
    86→	defer span.End()
    87→
    88→	resChan := make(chan error)
    89→	verificationSet := &signatureVerifier{set: set.Copy(), resChan: resChan}
    90→	s.signatureChan <- verificationSet
    91→
    92→	resErr := <-resChan
    93→	// If verification fails we fallback to individual verification
    94→	// of each signature set.
    95→	if resErr != nil {
    96→		log.WithError(resErr).Tracef("Could not perform batch verification of %s", message)
    97→		verified, err := set.Verify()
    98→		if err != nil {
    99→			verErr := errors.Wrapf(err, "Could not verify %s", message)
   100→			tracing.AnnotateError(span, verErr)
   101→			return pubsub.ValidationReject, verErr
   102→		}
   103→		if !verified {
   104→			verErr := errors.Errorf("Verification of %s failed", message)
   105→			tracing.AnnotateError(span, verErr)
   106→			return pubsub.ValidationReject, verErr
   107→		}
   108→	}
   109→	return pubsub.ValidationAccept, nil
   110→}
   111→
   112→func verifyBatch(verifierBatch []*signatureVerifier) {
   113→	if len(verifierBatch) == 0 {
   114→		return
   115→	}
   116→	aggSet := verifierBatch[0].set
   117→
   118→	for i := 1; i < len(verifierBatch); i++ {
   119→		aggSet = aggSet.Join(verifierBatch[i].set)
   120→	}
   121→	var verificationErr error
   122→
   123→	aggSet, verificationErr = performBatchAggregation(aggSet)
   124→	if verificationErr == nil {
   125→		verified, err := aggSet.Verify()
   126→		switch {
   127→		case err != nil:
   128→			verificationErr = err
   129→		case !verified:
   130→			verificationErr = errors.New("batch signature verification failed")
   131→		}
   132→	}
   133→	for i := 0; i < len(verifierBatch); i++ {
   134→		verifierBatch[i].resChan <- verificationErr
   135→	}
   136→}
   137→
   138→func performBatchAggregation(aggSet *bls.SignatureBatch) (*bls.SignatureBatch, error) {
   139→	currLen := len(aggSet.Signatures)
   140→	num, aggSet, err := aggSet.RemoveDuplicates()
   141→	if err != nil {
   142→		return nil, err
   143→	}
   144→	duplicatesRemovedCounter.Add(float64(num))
   145→	// Aggregate batches in the provided signature batch.
   146→	aggSet, err = aggSet.AggregateBatch()
   147→	if err != nil {
   148→		return nil, err
   149→	}
   150→	// Record number of signature sets successfully batched.
   151→	if currLen > len(aggSet.Signatures) {
   152→		numberOfSetsAggregated.Observe(float64(currLen - len(aggSet.Signatures)))
   153→	}
   154→	return aggSet, nil
   155→}
   156→
   157→func (s *Service) validateWithKzgBatchVerifier(ctx context.Context, dataColumns []blocks.RODataColumn) (pubsub.ValidationResult, error) {
   158→	_, span := trace.StartSpan(ctx, "sync.validateWithKzgBatchVerifier")
   159→	defer span.End()
   160→
   161→	timeout := time.Duration(params.BeaconConfig().SecondsPerSlot) * time.Second
   162→
   163→	resChan := make(chan error)
   164→	verificationSet := &kzgVerifier{dataColumns: dataColumns, resChan: resChan}
   165→	s.kzgChan <- verificationSet
   166→
   167→	ctx, cancel := context.WithTimeout(ctx, timeout)
   168→	defer cancel()
   169→
   170→	select {
   171→	case <-ctx.Done():
   172→		return pubsub.ValidationIgnore, ctx.Err() // parent context canceled, give up
   173→	case err := <-resChan:
   174→		if err != nil {
   175→			log.WithError(err).Trace("Could not perform batch verification")
   176→			tracing.AnnotateError(span, err)
   177→			return s.validateUnbatchedColumnsKzg(ctx, dataColumns)
   178→		}
   179→	}
   180→	return pubsub.ValidationAccept, nil
   181→}
   182→
   183→func (s *Service) validateUnbatchedColumnsKzg(ctx context.Context, columns []blocks.RODataColumn) (pubsub.ValidationResult, error) {
   184→	_, span := trace.StartSpan(ctx, "sync.validateUnbatchedColumnsKzg")
   185→	defer span.End()
   186→	if err := peerdas.VerifyDataColumnsSidecarKZGProofs(columns); err != nil {
   187→		err = errors.Wrap(err, "could not verify")
   188→		tracing.AnnotateError(span, err)
   189→		return pubsub.ValidationReject, err
   190→	}
   191→	return pubsub.ValidationAccept, nil
   192→}
   193→
   194→func verifyKzgBatch(kzgBatch []*kzgVerifier) {
   195→	if len(kzgBatch) == 0 {
   196→		return
   197→	}
   198→
   199→	allDataColumns := make([]blocks.RODataColumn, 0, len(kzgBatch))
   200→	for _, kzgVerifier := range kzgBatch {
   201→		allDataColumns = append(allDataColumns, kzgVerifier.dataColumns...)
   202→	}
   203→
   204→	var verificationErr error
   205→	err := peerdas.VerifyDataColumnsSidecarKZGProofs(allDataColumns)
   206→	if err != nil {
   207→		verificationErr = errors.Wrap(err, "batch KZG verification failed")
   208→	}
   209→
   210→	// Send the same result to all verifiers in the batch
   211→	for _, verifier := range kzgBatch {
   212→		verifier.resChan <- verificationErr
   213→	}
   214→}
